-- 이미 있는 가게에 합성 이력 덧붙이기 (ai/scripts/make_seed_sql.py --into-existing 가 만든다. 손으로 고치지 않는다)
-- 원본: gen/*.csv · 대상 가게: store_id=__DEMO_STORE_ID__ (가게 · 계정 · 메뉴 · 재료 · 레시피는 넣지 않는다)


-- 대상 가게가 정확히 1곳이고, 판매 · 거래처 상품 · 실사가 없고(이중 적재 방지), 생성에 쓴 메뉴 · 재료가 다 있어야 한다
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM store WHERE id = __DEMO_STORE_ID__;
  IF n = 0 THEN RAISE EXCEPTION 'seed.sql(--into-existing): 가게를 찾을 수 없다 — store_id=__DEMO_STORE_ID__'; END IF;
  IF n > 1 THEN RAISE EXCEPTION 'seed.sql(--into-existing): 가게가 하나가 아니다 — store_id=__DEMO_STORE_ID__ % 곳', n; END IF;
  IF EXISTS (SELECT 1 FROM pos_sale WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)) OR EXISTS (SELECT 1 FROM supplier_product WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)) OR EXISTS (SELECT 1 FROM stock_count WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)) THEN
    RAISE EXCEPTION 'seed.sql(--into-existing): store_id=__DEMO_STORE_ID__ 에 이미 판매 · 거래처 상품 · 실사가 있다 (이중 적재 방지)'; END IF;
  SELECT count(*) INTO n FROM menu WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND name IN ('"바사삭" 새우튀김만두 6개', '대박할인! 내맘대로 3인분', '고기만두 10개', '김치만두 10개', '새우만두 6개');
  IF n <> 5 THEN RAISE EXCEPTION 'seed.sql(--into-existing): store_id=__DEMO_STORE_ID__ 에 생성에 쓴 메뉴가 % / 5 개만 있다', n; END IF;
  SELECT count(*) INTO n FROM ingredient WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND name IN ('만두피', '새우', '부추', '식용유', '돼지고기', '양배추', '간장 소스', '김치');
  IF n <> 8 THEN RAISE EXCEPTION 'seed.sql(--into-existing): store_id=__DEMO_STORE_ID__ 에 생성에 쓴 재료가 % / 8 개만 있다', n; END IF;
END $$;

-- 넣기 전부터 있던 매입 문서 · 발주서 (발주서 연결 · 검증에서 뺀다)
CREATE TEMP TABLE seed_old_doc ON COMMIT DROP AS SELECT id FROM purchase_doc WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__);
CREATE TEMP TABLE seed_old_po ON COMMIT DROP AS SELECT id FROM purchase_order WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__);

-- 거래처: 그 가게에 같은 이름이 없는 것만 (있는 거래처 행은 그대로 둔다). 마감 시각 · 배송 요일은 발주 주기에 맞춘 값
INSERT INTO supplier (store_id, name, channel, lead_time_days, order_cycle_days, min_order_amount, cutoff_time, delivery_days)
SELECT st.id, v.name, v.channel, v.lead_time_days::integer, v.order_cycle_days::integer, v.min_order_amount::numeric, v.cutoff_time::time, string_to_array(v.delivery_days, ',')
FROM (VALUES
    ('푸른식자재', 'KAKAO', 2, 3, 50000, '18:00', 'MON,THU'),
    ('새벽청과', 'KAKAO', 1, 1, 30000, '18:00', 'MON,TUE,WED,THU,FRI,SAT,SUN'),
    ('한빛축산', 'KAKAO', 1, 2, 100000, '18:00', 'MON,WED,FRI')
) AS v(name, channel, lead_time_days, order_cycle_days, min_order_amount, cutoff_time, delivery_days)
CROSS JOIN (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AS st
WHERE NOT EXISTS (SELECT 1 FROM supplier x WHERE x.store_id = st.id AND x.name = v.name);

INSERT INTO supplier_product (store_id, supplier_id, ingredient_id, product_name, pack_unit, base_qty_per_pack, moq, price)
SELECT st.id, s.id, i.id, v.product_name, v.pack_unit, v.base_qty_per_pack::numeric, v.moq::numeric, v.price::numeric
FROM (VALUES
    ('푸른식자재', '만두피', '만두피 50개', '봉', 50, 1, 20000),
    ('푸른식자재', '새우', '칵테일새우 100마리', '봉', 100, 1, 18000),
    ('새벽청과', '부추', '부추 4kg', '박스', 4000, 1, 12000),
    ('푸른식자재', '식용유', '대두유 18L', '통', 18000, 1, 52000),
    ('한빛축산', '돼지고기', '돼지 앞다리살 5kg', '팩', 5000, 1, 45000),
    ('새벽청과', '양배추', '양배추 8kg', '망', 8000, 1, 12000),
    ('푸른식자재', '간장 소스', '간장 소스 20L', '통', 20000, 1, 60000),
    ('푸른식자재', '김치', '포기김치 10kg', '박스', 10000, 1, 35000)
) AS v(supplier_name, ingredient_name, product_name, pack_unit, base_qty_per_pack, moq, price)
CROSS JOIN (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AS st
JOIN supplier s ON s.store_id = st.id AND s.name = v.supplier_name
JOIN ingredient i ON i.store_id = st.id AND i.name = v.ingredient_name;

