) AS v(doc_supplier, doc_date, line_no, raw_name, qty, unit, unit_price, amount, sp_supplier, sp_name, ingredient_name, status)
CROSS JOIN (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AS st
JOIN supplier ds ON ds.store_id = st.id AND ds.name = v.doc_supplier
JOIN purchase_doc pd ON pd.store_id = st.id AND pd.supplier_id = ds.id AND pd.doc_date = v.doc_date::date AND pd.id NOT IN (SELECT id FROM seed_old_doc)
LEFT JOIN supplier ss ON ss.store_id = st.id AND ss.name = v.sp_supplier
LEFT JOIN supplier_product sp ON sp.supplier_id = ss.id AND sp.product_name = v.sp_name
LEFT JOIN ingredient i ON i.store_id = st.id AND i.name = v.ingredient_name;

INSERT INTO stock_count (store_id, ingredient_id, counted_at, qty)
SELECT st.id, i.id, v.counted_at::timestamptz, v.qty::numeric
FROM (VALUES
    ('만두피', '2024-11-12 23:59:59+09', 1567.2),
    ('새우', '2024-11-12 23:59:59+09', 4550.2),
    ('부추', '2024-11-12 23:59:59+09', 5852.2),
    ('식용유', '2024-11-12 23:59:59+09', 1421.7),
    ('돼지고기', '2024-11-12 23:59:59+09', 149224.8),
    ('양배추', '2024-11-12 23:59:59+09', 21673.5),
    ('간장 소스', '2024-11-12 23:59:59+09', 4472.8),
    ('김치', '2024-11-12 23:59:59+09', 64473.4)
) AS v(ingredient_name, counted_at, qty)
CROSS JOIN (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AS st
JOIN ingredient i ON i.store_id = st.id AND i.name = v.ingredient_name;

-- seed 검증 (--into-existing): 이름으로 찾는 JOIN 이 행을 떨구거나 연결을 비우면 멈춘다 (트랜잭션 안이라 전체가 되돌려진다)
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM supplier WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND name IN ('푸른식자재', '새벽청과', '한빛축산'); IF n <> 3 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ supplier % 행 (기대 3)', n; END IF;
  SELECT count(*) INTO n FROM supplier_product WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__); IF n <> 8 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ supplier_product % 행 (기대 8)', n; END IF;
  SELECT count(*) INTO n FROM pos_sale WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__); IF n <> 6597 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ pos_sale % 행 (기대 6597)', n; END IF;
  SELECT count(*) INTO n FROM store_closed_day WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND closed_date IN ('2024-11-25', '2024-11-28', '2024-12-08', '2024-12-24', '2025-01-03', '2025-01-07', '2025-01-29', '2025-02-16', '2025-02-28', '2025-03-23', '2025-03-30', '2025-04-12', '2025-04-22', '2025-05-10', '2025-05-31', '2025-06-04', '2025-06-24', '2025-07-05', '2025-07-18', '2025-08-28', '2025-08-29', '2025-09-27', '2025-09-28', '2025-10-06', '2025-10-16', '2025-10-17', '2025-11-07', '2025-11-17', '2025-12-29', '2025-12-30', '2026-01-08', '2026-01-29', '2026-02-12', '2026-02-15', '2026-02-17', '2026-03-14', '2026-03-25', '2026-04-24', '2026-04-25', '2026-05-18', '2026-05-29', '2026-06-02', '2026-06-09', '2026-07-03', '2026-07-09', '2026-08-21', '2026-08-25', '2026-09-07', '2026-09-25', '2026-09-30', '2026-10-13', '2026-10-21', '2026-11-02', '2026-11-03'); IF n <> 54 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ store_closed_day % 행 (기대 54)', n; END IF;
  SELECT count(*) INTO n FROM purchase_doc WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND id NOT IN (SELECT id FROM seed_old_doc); IF n <> 995 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ purchase_doc % 행 (기대 995)', n; END IF;
  SELECT count(*) INTO n FROM purchase_doc_line l WHERE l.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND l.doc_id NOT IN (SELECT id FROM seed_old_doc); IF n <> 1611 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ purchase_doc_line % 행 (기대 1611)', n; END IF;
  SELECT count(*) INTO n FROM purchase_doc_line l WHERE l.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND l.doc_id NOT IN (SELECT id FROM seed_old_doc) AND l.supplier_product_id IS NULL; IF n <> 0 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ purchase_doc_line.supplier_product_id NULL % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM purchase_doc_line l WHERE l.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND l.doc_id NOT IN (SELECT id FROM seed_old_doc) AND l.ingredient_id IS NULL; IF n <> 0 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ purchase_doc_line.ingredient_id NULL % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM stock_count WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__); IF n <> 8 THEN RAISE EXCEPTION 'seed 검증 실패: store_id=__DEMO_STORE_ID__ stock_count % 행 (기대 8)', n; END IF;
END $$;

-- ===== 화면 충족 (--into-existing): 대표 상품(빈 재료만) · 단가 이력 · 마지막 날 실사 =====
UPDATE ingredient AS i SET primary_supplier_product_id = sp.id, unit_status = 'LOCKED'
FROM (VALUES
    ('만두피', '푸른식자재', '만두피 50개'),
    ('새우', '푸른식자재', '칵테일새우 100마리'),
    ('부추', '새벽청과', '부추 4kg'),
    ('식용유', '푸른식자재', '대두유 18L'),
    ('돼지고기', '한빛축산', '돼지 앞다리살 5kg'),
    ('양배추', '새벽청과', '양배추 8kg'),
    ('간장 소스', '푸른식자재', '간장 소스 20L'),
    ('김치', '푸른식자재', '포기김치 10kg')
) AS v(ingredient_name, supplier_name, product_name)
JOIN supplier s ON s.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND s.name = v.supplier_name
JOIN supplier_product sp ON sp.supplier_id = s.id AND sp.product_name = v.product_name
WHERE i.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND i.name = v.ingredient_name AND i.primary_supplier_product_id IS NULL;

-- 이번에 넣은 매입 문서 줄마다 단가 이력 1행
INSERT INTO price_history (store_id, supplier_product_id, price, unit, observed_at, source, doc_line_id)
SELECT l.store_id, l.supplier_product_id, l.unit_price, COALESCE(l.unit, 'PACK'), pd.doc_date::timestamp AT TIME ZONE st.timezone, 'DOC', l.id
FROM purchase_doc_line l
JOIN store st ON st.id = l.store_id AND st.id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)
JOIN purchase_doc pd ON pd.id = l.doc_id AND pd.store_id = st.id AND pd.id NOT IN (SELECT id FROM seed_old_doc)
WHERE l.supplier_product_id IS NOT NULL AND l.unit_price > 0
ORDER BY pd.doc_date, pd.id, l.line_no;

-- 마지막 날 마감 재고를 다음 날 0시 실사로 (_screen_sql 과 같은 이유)
INSERT INTO stock_count (store_id, ingredient_id, counted_at, qty)
SELECT st.id, i.id, v.counted_at::timestamptz, v.qty::numeric
FROM (VALUES
    ('만두피', '2026-11-12 00:00:00+09', 189.2),
    ('새우', '2026-11-12 00:00:00+09', 730.2),
    ('부추', '2026-11-12 00:00:00+09', 9572.2),
    ('식용유', '2026-11-12 00:00:00+09', 8531.7),
    ('돼지고기', '2026-11-12 00:00:00+09', 29024.8),
    ('양배추', '2026-11-12 00:00:00+09', 13173.5),
    ('간장 소스', '2026-11-12 00:00:00+09', 4847.8),
    ('김치', '2026-11-12 00:00:00+09', 20473.4)
) AS v(ingredient_name, counted_at, qty)
CROSS JOIN (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AS st
JOIN ingredient i ON i.store_id = st.id AND i.name = v.ingredient_name;

-- seed 화면 충족 검증 (--into-existing)
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM ingredient WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND name IN ('만두피', '새우', '부추', '식용유', '돼지고기', '양배추', '간장 소스', '김치') AND primary_supplier_product_id IS NULL; IF n <> 0 THEN RAISE EXCEPTION 'seed 화면 충족 검증 실패: store_id=__DEMO_STORE_ID__ ingredient.primary_supplier_product_id NULL % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM supplier WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND name IN ('푸른식자재', '새벽청과', '한빛축산') AND (lead_time_days IS NULL OR order_cycle_days IS NULL); IF n <> 0 THEN RAISE EXCEPTION 'seed 화면 충족 검증 실패: store_id=__DEMO_STORE_ID__ supplier 리드타임 · 발주 주기 NULL % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM price_history WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND source = 'DOC'; IF n <> 1611 THEN RAISE EXCEPTION 'seed 화면 충족 검증 실패: store_id=__DEMO_STORE_ID__ price_history DOC % 행 (기대 1611)', n; END IF;
  SELECT count(*) INTO n FROM stock_count WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__); IF n <> 16 THEN RAISE EXCEPTION 'seed 화면 충족 검증 실패: store_id=__DEMO_STORE_ID__ stock_count % 행 (기대 16)', n; END IF;
END $$;

-- ===== 발주 이력 (S15P31A308-242): 매입 문서마다 보내고 입고 끝난 발주서 1장 · 문서 줄마다 품목 1줄 =====
-- 발주서 → 문서 연결은 (거래처, 주문 시각) 으로 찾는다. 같은 거래처 · 같은 날 문서가 두 장이 없어(_store_sql 확인) 겹치지 않는다
WITH src AS (
    SELECT pd.id AS doc_id, pd.store_id, pd.supplier_id,
           ((pd.doc_date - COALESCE(s.lead_time_days, 1)) + TIME '15:00') AT TIME ZONE st.timezone AS sent_at
    FROM purchase_doc pd
    JOIN store st ON st.id = pd.store_id AND st.id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)
    JOIN supplier s ON s.id = pd.supplier_id AND s.store_id = st.id
    WHERE pd.doc_date IS NOT NULL AND pd.id NOT IN (SELECT id FROM seed_old_doc)
      AND EXISTS (SELECT 1 FROM purchase_doc_line l WHERE l.doc_id = pd.id AND l.store_id = st.id AND l.supplier_product_id IS NOT NULL AND l.ingredient_id IS NOT NULL AND l.qty > 0)
      AND NOT EXISTS (SELECT 1 FROM purchase_doc_line l WHERE l.doc_id = pd.id AND l.store_id = st.id
                      AND l.status = 'CONFIRMED' AND l.ingredient_id IS NOT NULL AND NOT (l.supplier_product_id IS NOT NULL AND l.ingredient_id IS NOT NULL AND l.qty > 0))
), po AS (
    INSERT INTO purchase_order (store_id, supplier_id, status, created_at, sent_at)
    SELECT store_id, supplier_id, 'SENT', sent_at, sent_at FROM src ORDER BY sent_at, doc_id
    RETURNING id, supplier_id, sent_at
)
UPDATE purchase_doc AS d SET purchase_order_id = po.id
FROM src JOIN po ON po.supplier_id = src.supplier_id AND po.sent_at = src.sent_at
WHERE d.id = src.doc_id AND d.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND d.id NOT IN (SELECT id FROM seed_old_doc);

INSERT INTO purchase_order_item (store_id, po_id, supplier_product_id, ingredient_id, qty, expected_date, received_qty, received_at, received_unit_price)
SELECT l.store_id, pd.purchase_order_id, l.supplier_product_id, l.ingredient_id, l.qty, pd.doc_date, l.qty, (pd.doc_date + TIME '17:00') AT TIME ZONE st.timezone, NULLIF(l.unit_price, 0)
FROM purchase_doc_line l
JOIN store st ON st.id = l.store_id AND st.id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__)
JOIN purchase_doc pd ON pd.id = l.doc_id AND pd.store_id = st.id AND pd.purchase_order_id IS NOT NULL AND pd.id NOT IN (SELECT id FROM seed_old_doc)
WHERE l.supplier_product_id IS NOT NULL AND l.ingredient_id IS NOT NULL AND l.qty > 0
ORDER BY pd.doc_date, pd.id, l.line_no;

-- seed 발주 이력 검증: 발주서 · 품목이 덜 들어가거나 입고 예정 · 실사 뒤 입고가 생기면 멈춘다 (트랜잭션 안이라 전체가 되돌려진다)
DO $$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM purchase_order WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND id NOT IN (SELECT id FROM seed_old_po); IF n <> 995 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_order % 행 (기대 995)', n; END IF;
  SELECT count(*) INTO n FROM purchase_order WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND id NOT IN (SELECT id FROM seed_old_po) AND (status <> 'SENT' OR sent_at IS NULL); IF n <> 0 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_order SENT 아님 % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM purchase_order_item WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND po_id NOT IN (SELECT id FROM seed_old_po); IF n <> 1611 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_order_item % 행 (기대 1611)', n; END IF;
  SELECT count(*) INTO n FROM purchase_order_item WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND po_id NOT IN (SELECT id FROM seed_old_po) AND (received_at IS NULL OR received_qty IS NULL); IF n <> 0 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_order_item 입고 안 됨 % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM purchase_order_item poi WHERE poi.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND poi.po_id NOT IN (SELECT id FROM seed_old_po) AND poi.received_at >= (SELECT max(sc.counted_at) FROM stock_count sc WHERE sc.store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND sc.ingredient_id = poi.ingredient_id); IF n <> 0 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_order_item 마지막 실사 뒤 입고 % 행 (기대 0)', n; END IF;
  SELECT count(*) INTO n FROM purchase_doc WHERE store_id = (SELECT id FROM store WHERE id = __DEMO_STORE_ID__) AND id NOT IN (SELECT id FROM seed_old_doc) AND purchase_order_id IS NULL; IF n <> 0 THEN RAISE EXCEPTION '발주 이력 검증 실패: store_id=__DEMO_STORE_ID__ purchase_doc 발주서 미연결 % 행 (기대 0)', n; END IF;
END $$;

